import{_ as i,c as e,o as a,ae as o}from"./chunks/framework.DMK_uHmU.js";const n="/help-center/assets/topics-manage.Bv_qyLAU.png",s="/help-center/assets/topics-add-new.UX_2wuWD.png",m=JSON.parse('{"title":"Topic Management Guide","description":"","frontmatter":{},"headers":[],"relativePath":"Administration/AI-Management/Settings/topics.md","filePath":"Administration/AI-Management/Settings/topics.md"}'),l={name:"Administration/AI-Management/Settings/topics.md"};function r(c,t,p,d,g,h){return a(),e("div",null,t[0]||(t[0]=[o('<h1 id="topic-management-guide" tabindex="-1">Topic Management Guide <a class="header-anchor" href="#topic-management-guide" aria-label="Permalink to &quot;Topic Management Guide&quot;">​</a></h1><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>The Topic Management system allows administrators to create and manage primary categories for organizing content throughout the platform. Topics provide a structured categorization system that helps organize content and generate meaningful analytics about user interactions. This guide explains how to effectively use the Topic Management interface to create and maintain topics.</p><h2 id="accessing-topic-management" tabindex="-1">Accessing Topic Management <a class="header-anchor" href="#accessing-topic-management" aria-label="Permalink to &quot;Accessing Topic Management&quot;">​</a></h2><p>The Topic Management component is accessible to users with specific roles:</p><ul><li>Admin</li><li>Content</li><li>Manager</li></ul><p>This interface is typically found in the system settings under AI Settings or Content Management sections.</p><h2 id="understanding-topics" tabindex="-1">Understanding Topics <a class="header-anchor" href="#understanding-topics" aria-label="Permalink to &quot;Understanding Topics&quot;">​</a></h2><p>Topics are primary categories that provide high-level organization for content:</p><ol><li><p><strong>Purpose</strong>:</p><ul><li>Create main content categories</li><li>Establish consistent organizational structure</li><li>Enable analytics and reporting by category</li><li>Facilitate content management and discovery</li></ul></li><li><p><strong>Characteristics</strong>:</p><ul><li>Single primary topic per content item</li><li>System-defined (managed centrally)</li><li>Used in reporting and analytics</li><li>More formal than tags</li></ul></li><li><p><strong>Benefits</strong>:</p><ul><li>Consistent content organization</li><li>Structured navigation</li><li>Insights into user interests</li><li>Clear content ownership</li></ul></li></ol><h2 id="topic-management-interface" tabindex="-1">Topic Management Interface <a class="header-anchor" href="#topic-management-interface" aria-label="Permalink to &quot;Topic Management Interface&quot;">​</a></h2><p>The Topic Management interface consists of these key components:</p><ol><li><strong>Header</strong>: Title &quot;Manage Topics&quot; with explanatory text</li><li><strong>Topic List</strong>: List of existing system topics</li><li><strong>Add Topic Button</strong>: Button to create new topics</li><li><strong>Topic Input Fields</strong>: Text fields for entering topic names</li></ol><h2 id="managing-topics" tabindex="-1">Managing Topics <a class="header-anchor" href="#managing-topics" aria-label="Permalink to &quot;Managing Topics&quot;">​</a></h2><p><img src="'+n+'" alt="homepage"></p><h3 id="adding-topics" tabindex="-1">Adding Topics <a class="header-anchor" href="#adding-topics" aria-label="Permalink to &quot;Adding Topics&quot;">​</a></h3><p>To create a new topic:</p><p><img src="'+s+'" alt="homepage"></p><ol><li>Click the &quot;Add New Topic&quot; button at the bottom of the topic list</li><li>A new input field will appear</li><li>Enter the desired topic name in the field <ul><li>Use clear, descriptive terminology</li><li>Consider organizational structure</li><li>Choose names that make sense to end users</li></ul></li><li>The topic will be validated as you type</li><li>When you save the settings page, all valid topics will be saved</li></ol><p>Topics added through this interface become available across the system for:</p><ul><li>Content categorization</li><li>Blueprint organization</li><li>Knowledge base classification</li><li>Analytics and reporting</li></ul><h3 id="editing-topics" tabindex="-1">Editing Topics <a class="header-anchor" href="#editing-topics" aria-label="Permalink to &quot;Editing Topics&quot;">​</a></h3><p>To modify an existing topic:</p><ol><li>Locate the topic in the list</li><li>Click in its text field</li><li>Edit the topic name as desired</li><li>Changes are applied when the settings page is saved</li></ol><p><strong>Note</strong>: Editing a topic changes it across all content where it&#39;s applied. This is a global change that affects all items using that topic and any reports or analytics based on that topic.</p><h3 id="removing-topics" tabindex="-1">Removing Topics <a class="header-anchor" href="#removing-topics" aria-label="Permalink to &quot;Removing Topics&quot;">​</a></h3><p>To delete a topic:</p><ol><li>Locate the topic in the list</li><li>Click the trash icon (×) button on the right side of the topic</li><li>The topic is removed from the list</li><li>When settings are saved, the topic will be removed from the system</li></ol><p><strong>Important</strong>: Before removing a topic, ensure it is not in use. Content items using a deleted topic may be reassigned to a default topic or left without a topic, depending on system configuration.</p><h2 id="topic-usage" tabindex="-1">Topic Usage <a class="header-anchor" href="#topic-usage" aria-label="Permalink to &quot;Topic Usage&quot;">​</a></h2><p>Once created, topics are used throughout the system in various contexts:</p><h3 id="content-categorization" tabindex="-1">Content Categorization <a class="header-anchor" href="#content-categorization" aria-label="Permalink to &quot;Content Categorization&quot;">​</a></h3><p>When creating or editing content:</p><ul><li>Select a single topic from the available system topics</li><li>The topic defines the primary category for the content</li><li>Content can be filtered or grouped by topic</li></ul><h3 id="blueprint-organization" tabindex="-1">Blueprint Organization <a class="header-anchor" href="#blueprint-organization" aria-label="Permalink to &quot;Blueprint Organization&quot;">​</a></h3><p>When configuring AI Blueprints:</p><ul><li>Assign a primary topic to categorize the Blueprint</li><li>Use topics to organize Blueprints in listings</li><li>Filter Blueprint lists by selected topic</li></ul><h3 id="knowledge-base-classification" tabindex="-1">Knowledge Base Classification <a class="header-anchor" href="#knowledge-base-classification" aria-label="Permalink to &quot;Knowledge Base Classification&quot;">​</a></h3><p>When managing Knowledge Bases:</p><ul><li>Assign a primary topic to each Knowledge Base</li><li>Use topics to organize Knowledge Bases by department or function</li><li>Filter and group Knowledge Bases by topic</li></ul><h3 id="analytics-and-reporting" tabindex="-1">Analytics and Reporting <a class="header-anchor" href="#analytics-and-reporting" aria-label="Permalink to &quot;Analytics and Reporting&quot;">​</a></h3><p>Topics provide important data structure for analytics:</p><ul><li>User questions can be analyzed by topic</li><li>Usage patterns can be identified by topic</li><li>Content gaps can be detected within specific topics</li><li>Performance metrics can be compared across topics</li></ul><h2 id="topics-vs-tags" tabindex="-1">Topics vs. Tags <a class="header-anchor" href="#topics-vs-tags" aria-label="Permalink to &quot;Topics vs. Tags&quot;">​</a></h2><p>Understanding the difference between topics and tags:</p><table tabindex="0"><thead><tr><th>Feature</th><th>Topics</th><th>Tags</th></tr></thead><tbody><tr><td>Number per item</td><td>One primary topic</td><td>Multiple tags</td></tr><tr><td>Creation</td><td>Centrally managed</td><td>Central or ad-hoc</td></tr><tr><td>Purpose</td><td>Primary categorization</td><td>Secondary classification</td></tr><tr><td>Structure</td><td>Formal, consistent</td><td>Flexible, evolving</td></tr><tr><td>Analytics</td><td>Used in reporting</td><td>Less formal tracking</td></tr><tr><td>Selection</td><td>Select from pre-defined list</td><td>Select or create new</td></tr></tbody></table><p>Topics provide structured organization while tags offer flexible, multi-dimensional classification.</p><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><p>For effective topic management:</p><ol><li><p><strong>Strategic Planning</strong>:</p><ul><li>Create a comprehensive topic list before implementation</li><li>Align topics with organizational structure when appropriate</li><li>Consider content volume when defining topics</li><li>Avoid creating too many or too few topics</li></ul></li><li><p><strong>Naming Conventions</strong>:</p><ul><li>Use clear, descriptive names</li><li>Maintain consistent capitalization (typically Title Case)</li><li>Consider using nouns or noun phrases</li><li>Make topics intuitive for both creators and users</li></ul></li><li><p><strong>Topic Structure</strong>:</p><ul><li>Keep the total number of topics manageable (typically 10-20)</li><li>Ensure topics are distinct from each other</li><li>Cover all major content areas in your organization</li><li>Consider departmental or functional divisions</li></ul></li><li><p><strong>Governance</strong>:</p><ul><li>Establish clear guidelines for topic usage</li><li>Define who can create or modify topics</li><li>Document the purpose and scope of each topic</li><li>Review topic usage periodically to ensure consistency</li></ul></li></ol><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p><strong>Issue</strong>: Topics not appearing in content creation interfaces</p><ul><li>Refresh the interface to load the latest topics</li><li>Verify that topics were properly saved in the Topic Management interface</li><li>Check user permissions for topic visibility</li></ul><p><strong>Issue</strong>: Unable to add new topics</p><ul><li>Ensure you have the required permissions (Admin, Content, or Manager)</li><li>Check that the topic name is valid and not duplicated</li><li>Verify the topic field is not empty when trying to save</li></ul><p><strong>Issue</strong>: Analytics showing incorrect topic data</p><ul><li>Confirm topics are properly applied to content items</li><li>Check if topics have been renamed recently</li><li>Allow time for analytics to process topic changes</li></ul><p><strong>Issue</strong>: Too many or overlapping topics</p><ul><li>Develop a plan to consolidate similar topics</li><li>Focus on major categories rather than specific subjects</li><li>Consider using tags for more granular classification</li><li>Review your topic strategy with stakeholders</li></ul><p><strong>Issue</strong>: Content appears under unexpected topics</p><ul><li>Verify topic assignment for the content item</li><li>Check if topics have been renamed or deleted</li><li>Review any bulk operations that might have modified topics</li></ul><hr><p>For additional assistance with topic management, please contact your system administrator or refer to the platform documentation.</p>',63)]))}const f=i(l,[["render",r]]);export{m as __pageData,f as default};
